enum Direction {
  Up,    // 0
  Down,  // 1
  Left,  // 2
  Right, // 3
}

function move(dir: Direction): string {
  switch (dir) {
    case Direction.Up:
      return 'Moving up';
    case Direction.Down:
      return 'Moving down';
    case Direction.Left:
      return 'Moving left';
    case Direction.Right:
      return 'Moving right';
  }
}

move(Direction.Right);

enum UserRole {
  Admin = 'admin',
  Editor = 'editor',
  Viewer = 'viewer',
}

function canDelete(role: UserRole): boolean {
  return role === UserRole.Admin || role === UserRole.Editor;
}

const myRole: UserRole = UserRole.Editor;

